import{_ as a,m as n,n as e,q as l}from"./chunks/framework.DMDh-7Lg.js";const y=JSON.parse('{"title":"Persistence","description":"","frontmatter":{},"headers":[],"relativePath":"guides/persistence.md","filePath":"guides/persistence.md"}'),o={name:"guides/persistence.md"};function t(p,s,r,i,c,D){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h1><p>Klix can persist session state to disk. The implementation is intentionally lightweight: dataclass state becomes JSON, stored per session, and optionally migrated before reload.</p><p>This guide focuses on practical usage. For the underlying model, see <a href="./../concepts/state">State</a>.</p><h2 id="enable-persistence" tabindex="-1">Enable Persistence <a class="header-anchor" href="#enable-persistence" aria-label="Permalink to &quot;Enable Persistence&quot;">​</a></h2><p>Set <code>persist_session=True</code> when creating the app:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">ReleaseTool</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    version</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">0.1.0</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Deployment workflow helper</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    state_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">ReleaseState</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    persist_session</span><span style="color:#89DDFF;">=True,</span></span>
<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><p>That tells the app to:</p><ul><li>create a <code>SessionStateManager</code></li><li>save the current session state on exit</li></ul><h2 id="where-files-are-stored" tabindex="-1">Where Files Are Stored <a class="header-anchor" href="#where-files-are-stored" aria-label="Permalink to &quot;Where Files Are Stored&quot;">​</a></h2><p>Klix writes state files to:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>~/.klix/sessions/&lt;app-name&gt;/&lt;session-id&gt;.json</span></span></code></pre></div><p>Example:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>~/.klix/sessions/ReleaseTool/55fceba3-10da-4eb5-b3c2-18e76e7ef1e7.json</span></span></code></pre></div><p>The app name becomes the directory name. Each session gets its own file.</p><h2 id="what-is-saved" tabindex="-1">What Is Saved <a class="header-anchor" href="#what-is-saved" aria-label="Permalink to &quot;What Is Saved&quot;">​</a></h2><p>The current implementation saves:</p><ul><li><code>session_id</code></li><li><code>version</code></li><li>serialized dataclass state</li><li>basic metadata snapshot</li></ul><p>The state payload comes from <code>dataclasses.asdict(state)</code>.</p><p>That means persisted state should stay simple and JSON-friendly.</p><h2 id="loading-a-session" tabindex="-1">Loading A Session <a class="header-anchor" href="#loading-a-session" aria-label="Permalink to &quot;Loading A Session&quot;">​</a></h2><p>The state manager can load a session when you provide a session identifier through app configuration or your own startup flow.</p><p>The important implementation detail is this:</p><ul><li>enabling persistence alone guarantees save-on-exit</li><li>loading requires a known <code>session_id</code></li></ul><p>If your app wants “resume the latest session” behavior, you need to implement that policy yourself on top of the provided manager.</p><h2 id="add-a-migration-hook" tabindex="-1">Add A Migration Hook <a class="header-anchor" href="#add-a-migration-hook" aria-label="Permalink to &quot;Add A Migration Hook&quot;">​</a></h2><p>When your state model changes, register a migration function:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">state_migration</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> migrate_state</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">data</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> dict</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#FFCB6B;"> dict</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    if</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> in</span><span style="color:#BABED8;"> data </span><span style="color:#89DDFF;">and</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">active_profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> not</span><span style="color:#89DDFF;"> in</span><span style="color:#BABED8;"> data</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#BABED8;">        data</span><span style="color:#89DDFF;">[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">active_profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;"> =</span><span style="color:#BABED8;"> data</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">pop</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    data</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">setdefault</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">recent_runs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> [])</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#BABED8;"> data</span></span></code></pre></div><p>Klix calls this hook before reconstructing the dataclass.</p><p>Why this matters:</p><ul><li>old session files do not have to break new releases</li><li>migrations stay close to app code</li><li>you can evolve your state model gradually</li></ul><h2 id="practical-example" tabindex="-1">Practical Example <a class="header-anchor" href="#practical-example" aria-label="Permalink to &quot;Practical Example&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#BABED8;"> dataclasses </span><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> dataclass</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> field</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> klix</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">dataclass</span></span>
<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> ReleaseState</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">SessionState</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    active_profile</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">default</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#BABED8;">    recent_runs</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> list</span><span style="color:#89DDFF;">[</span><span style="color:#FFCB6B;">str</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;"> =</span><span style="color:#82AAFF;"> field</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">default_factory</span><span style="color:#89DDFF;">=</span><span style="color:#FFCB6B;">list</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">ReleaseTool</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    version</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">0.2.0</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Deployment workflow helper</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    state_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">ReleaseState</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    persist_session</span><span style="color:#89DDFF;">=True,</span></span>
<span class="line"><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">state_migration</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> migrate_state</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">data</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> dict</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#FFCB6B;"> dict</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    if</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> in</span><span style="color:#BABED8;"> data </span><span style="color:#89DDFF;">and</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">active_profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> not</span><span style="color:#89DDFF;"> in</span><span style="color:#BABED8;"> data</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#BABED8;">        data</span><span style="color:#89DDFF;">[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">active_profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;"> =</span><span style="color:#BABED8;"> data</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">pop</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">profile</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">    data</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">setdefault</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">recent_runs</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> [])</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#BABED8;"> data</span></span></code></pre></div><h2 id="limitations-to-understand" tabindex="-1">Limitations To Understand <a class="header-anchor" href="#limitations-to-understand" aria-label="Permalink to &quot;Limitations To Understand&quot;">​</a></h2><ul><li>Version handling is minimal. The current state manager writes a version field, but migration decisions are still up to your hook.</li><li>There is no built-in “list sessions” or “resume latest” command.</li><li>Persistence is focused on dataclass state, not on full replayable transcripts.</li></ul><p>Those constraints keep the framework small, but they are important when you plan a real tool.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Storing renderer or input engine objects in persisted state.</li><li>Assuming persistence automatically restores previous sessions with no identifier.</li><li>Writing migration hooks that mutate to a shape your dataclass still cannot accept.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./working-with-state">Working With State</a></li><li><a href="./../reference/config">Reference: Config</a></li><li><a href="./../examples/full-demo">Examples: Full Demo</a></li></ul>`,39)])])}const d=a(o,[["render",t]]);export{y as __pageData,d as default};
